using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using HakutaiKagami.Core.World;
using Xunit;
namespace HakutaiKagami.Tests;

public class RegionalBattleTests
{
    static WorldSession New(bool refuses = false, bool low = false, int count = 3) => new(RegionalBattle.Create(count, refuses, low));
    public static RegionalRequest Order(string id = "request:region", RegionalAction action = RegionalAction.Move, bool clerk = false) => new(new(id), ContractFixture.Officer, clerk ? ContractFixture.Clerk : ContractFixture.Officer, action, new(25000, -25000), new(65000, -25000));
    static void Issue(WorldSession s, RegionalRequest r) { Assert.Equal(ResultCode.Accepted, s.IssueRegional(r, s.Revision).Code); }
    static string State(WorldSession s) => ContractJson.CanonicalHash(s.DiagnosticSnapshot().Region!);
    [Fact] public void SharedTerrainElevationAndDiagonalSmoothing() { var p = RegionalGround.Plan(new(-45000, -45000), new(-15000, -15000), 0); Assert.Single(p); Assert.Equal(10000, RegionalGround.Height(new(75000, 5000))); Assert.Equal(0, RegionalGround.Height(new(5000, 5000))); Assert.Throws<InvalidDataException>(() => RegionalGround.Plan(new(5000, 5000), new(85000, 15000), 0)); Assert.Throws<InvalidDataException>(() => RegionalGround.Plan(new(35000, 65000), new(45000, 65000), 0)); }
    [Fact] public void SweptCollisionDetectsCrossingsBetweenEndpoints() { FieldLeg[] a = [new(new(-5000, 0), new(5000, 0), 0, 1, 10000, "grass")]; FieldLeg[] b = [new(new(0, -5000), new(0, 5000), 0, 1, 10000, "grass")]; Assert.True(RegionalGround.Conflict(a, a[0].From, b, b[0].From, 0, 1)); }
    [Fact] public void MovementHeightAndRetargetStayContinuous() { var s = New(); Issue(s, Order()); Assert.Equal("applied", s.DiagnosticSnapshot().Region!.Commands[0].Result); s.AdvanceTo(5); var before = s.DiagnosticSnapshot().Region!.Units[0].Position; Issue(s, Order("request:retarget") with { A = new(25000, -35000), B = new(65000, -35000) }); Assert.Equal(before, s.DiagnosticSnapshot().Region!.Units[0].Position); s.AdvanceTo(350); var w = s.DiagnosticSnapshot(); Assert.All(w.Region!.Units.Where(u => u.Commander == ContractFixture.Officer), u => Assert.Equal(-35000, u.Position.Y)); Assert.Equal(RegionalGround.Height(w.Region.Units[0].Position), w.Locations.Single(l => l.Actor == ContractFixture.Officer).HeightMm); }
    [Fact] public void BlockedOrderHoldsAtomicallyAndIdempotently() { var s = New(); var r = Order() with { A = new(85000, 15000), B = new(85000, 35000) }; Issue(s, r); Assert.Equal("blocked-hold", s.DiagnosticSnapshot().Region!.Commands[0].Result); Assert.All(s.DiagnosticSnapshot().Region!.Units, u => Assert.Equal(u.Home, u.Position)); Assert.Equal(ResultCode.AlreadyAccepted, s.IssueRegional(r, 0).Code); Assert.Equal(ResultCode.IdPayloadConflict, s.IssueRegional(r with { Action = RegionalAction.Hold }, s.Revision).Code); Assert.Equal(ResultCode.StateChanged, s.IssueRegional(Order("request:stale"), 0).Code); }
    [Theory][InlineData(false)][InlineData(true)] public void RecipientActsOnlyAfterPhysicalDeliveryAndReport(bool refuses) { var s = New(refuses); Issue(s, Order(clerk: true)); var w = s.DiagnosticSnapshot(); var due = w.Region!.Deliveries[0].DueAt; s.AdvanceTo(due - 1); Assert.Null(s.DiagnosticSnapshot().Region!.Commands[0].RecognizedAt); s.AdvanceTo(due); w = s.DiagnosticSnapshot(); Assert.Equal(refuses ? "refused" : "applied", w.Region!.Commands[0].Result); Assert.Equal("発送済・結果未確認", RegionalBattle.Status(w, w.Region.Commands[0], ContractFixture.Officer)); var report = w.Region.Deliveries.Last().DueAt; s.AdvanceTo(report); w = s.DiagnosticSnapshot(); Assert.Equal(refuses ? "refused" : "applied", RegionalBattle.Status(w, w.Region!.Commands[0], ContractFixture.Officer)); }
    [Fact] public void LowMoraleDoesNotCauseUnprovokedRouting() { var s = New(low: true); s.AdvanceTo(10); Assert.All(s.DiagnosticSnapshot().Region!.Units, u => Assert.Equal("standing", u.Phase)); }
    [Theory][InlineData(false)][InlineData(true)] public void ContactLossesAndMoraleAreOncePerSecondAndRecover(bool low) { var s = New(low: low); Issue(s, Order(action: RegionalAction.Engage)); Assert.Equal("applied", s.DiagnosticSnapshot().Region!.Commands[0].Result); s.AdvanceTo(300); var w = s.DiagnosticSnapshot(); Assert.NotEmpty(w.Region!.Losses); Assert.Equal(w.Region.Losses.Length, w.Region.Losses.Select(l => (l.At, l.Unit)).Distinct().Count()); Assert.Contains(w.Region.Units, u => u.Phase is "routed" or "destroyed"); var recovered = new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w))); s.AdvanceTo(330); recovered.AdvanceTo(330); Assert.Equal(State(s), State(recovered)); }
    [Fact] public void AuthorityIsCheckedAgainAtReceipt() { var w = RegionalBattle.Create(); w.ServiceBonds = w.ServiceBonds.Select(b => b.Subject == ContractFixture.Clerk ? b with { Until = 2 } : b).ToArray(); var s = new WorldSession(w); Issue(s, Order(clerk: true)); s.AdvanceTo(40); Assert.Equal("authority-refused", s.DiagnosticSnapshot().Region!.Commands[0].Result); }
    [Theory][InlineData(3)][InlineData(12)] public void ScaleAndChunkingPreservePositionsAndNoOverlap(int count) { var a = New(count: count); var b = New(count: count); var r = Order() with { A = new(-45000, -55000), B = new(65000, -55000) }; Issue(a, r); Issue(b, r); Assert.Equal("applied", a.DiagnosticSnapshot().Region!.Commands[0].Result); a.AdvanceTo(160); for (int i = 1; i <= 160; i++) b.AdvanceTo(i); Assert.Equal(State(a), State(b)); ContractValidation.Validate(a.DiagnosticSnapshot()); Assert.Equal(count * 3, a.DiagnosticSnapshot().Region!.Units.Length); }
    [Theory][InlineData(0)][InlineData(7)][InlineData(60)][InlineData(220)] public void GenerationSaveRestorePreservesMovementCombatAndViews(int at) { var s = New(); Issue(s, Order(action: RegionalAction.Engage)); s.AdvanceTo(at); var root = Path.Combine(Path.GetTempPath(), "region-" + Guid.NewGuid().ToString("N")); var store = new GenerationSaveStore(root, RegionalBattle.Create().Definitions); store.Save(s, "test", s.DiagnosticSnapshot().WorldId, new(.375, 1)); var host = new WorldSessionHost(New()); Assert.Equal(ResultCode.Accepted, host.CommitLoad(store.Prepare("test"), host.Current, host.Current.Revision)); Assert.Equal(State(s), State(host.Current)); host.Current.SetPaused(false); s.AdvanceTo(300); host.Current.AdvanceTo(300); Assert.Equal(State(s), State(host.Current)); Assert.Equal(ContractJson.Write(RegionalBattle.View(s.DiagnosticSnapshot(), ContractFixture.Officer)), ContractJson.Write(RegionalBattle.View(host.Current.DiagnosticSnapshot(), ContractFixture.Officer))); }
    [Fact]
    public void RoadAndSiteRoundTripSharesClock()
    {
        var s = New(); Issue(s, Order()); s.AdvanceTo(300); Issue(s, Order("request:home", RegionalAction.Retreat)); s.AdvanceTo(1000); Assert.Equal("applied", s.DiagnosticSnapshot().Region!.Commands.Last().Result);
        Assert.Equal(ResultCode.Accepted, s.SetRegionalActive(false, s.Revision).Code);
        Assert.Equal(ResultCode.Accepted, s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(), "request:road", "fork"), s.Revision).Code); s.AdvanceTo(100000);
        Assert.Equal(ResultCode.Accepted, s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(), "request:road-back", "castle"), s.Revision).Code); s.AdvanceTo(200000);
        Assert.Equal(ResultCode.Accepted, s.SetRegionalActive(true, s.Revision).Code); Assert.Equal(s.Seconds, s.DiagnosticSnapshot().Region!.Tick);
    }
    [Fact] public void MissingModuleAndForgedHeightOrLossRejected() { var w = RegionalBattle.Create(); w.Region = null; Assert.Throws<InvalidDataException>(() => ContractValidation.Validate(w)); w = RegionalBattle.Create(); w.Locations = w.Locations.Select(l => l.Actor == ContractFixture.Officer ? l with { HeightMm = 999 } : l).ToArray(); Assert.Throws<InvalidDataException>(() => ContractValidation.Validate(w)); w = RegionalBattle.Create(); w.Region = w.Region! with { Units = w.Region.Units.Select((u, i) => i == 0 ? u with { Soldiers = 1 } : u).ToArray() }; Assert.Throws<InvalidDataException>(() => ContractValidation.Validate(w)); }

    [Fact] public void ConcurrentCommandsHoldAndPhysicallyReportConflict() { var s = New(); Issue(s, Order("request:one", clerk: true)); Issue(s, Order("request:two", clerk: true) with { A = new(-35000, 25000) }); s.AdvanceTo(60); var w = s.DiagnosticSnapshot(); Assert.All(w.Region!.Commands, c => { Assert.Equal("conflict-hold", c.Result); Assert.Null(c.AppliedAt); Assert.Equal("conflict-hold", RegionalBattle.Status(w, c, ContractFixture.Officer)); }); Assert.All(w.Region.Units.Where(u => u.Commander == ContractFixture.Clerk), u => Assert.Equal(u.Home, u.Position)); }
    [Fact] public void AbsentRecipientDoesNotReceiveOrRevealFailureEarly() { var w = RegionalBattle.Create(); RegionalBattle.Issue(w, Order(clerk: true)); var d = w.Region!.Deliveries[0]; w.Region = w.Region with { Units = w.Region.Units.Select(u => u.Commander == ContractFixture.Clerk && u.Id == new EntityId("unit:clerk") ? u with { Position = new(-35000, 5000), RouteOrigin = new(-35000, 5000), Goal = new(-35000, 5000), Home = new(-35000, 5000) } : u).ToArray() }; RegionalBattle.Sync(w); var s = new WorldSession(w); s.AdvanceTo(d.DueAt); w = s.DiagnosticSnapshot(); Assert.Null(w.Region!.Commands[0].RecognizedAt); Assert.Equal("発送済・結果未確認", RegionalBattle.Status(w, w.Region.Commands[0], ContractFixture.Officer)); s.AdvanceTo(80); w = s.DiagnosticSnapshot(); Assert.Equal("失敗報告を受領", RegionalBattle.Status(w, w.Region!.Commands[0], ContractFixture.Officer)); }
    [Fact] public void OutOfSightHeadingAndStateStayAtLastObservation() { var s = New(); var before = RegionalBattle.View(s.DiagnosticSnapshot(), ContractFixture.Officer).Single(v => v.Unit == new EntityId("unit:region/2/0")); Issue(s, Order() with { A = new(-45000, -45000), B = new(-25000, -45000) }); s.AdvanceTo(150); var view = RegionalBattle.View(s.DiagnosticSnapshot(), ContractFixture.Officer).Single(v => v.Unit == before.Unit); Assert.False(view.Live); Assert.True(view.ObservedAt < 150); Assert.Equal(before.Heading, view.Heading); }
    [Fact] public void TamperedPathSpeedAndTraversalAreRejected() { var s = New(); Issue(s, Order()); var w = s.DiagnosticSnapshot(); var u = w.Region!.Units[0]; var path = u.Route.ToArray(); path[0] = path[0] with { Speed = 9999 }; w.Region = w.Region with { Units = w.Region.Units.Select(x => x.Id == u.Id ? x with { Route = path } : x).ToArray() }; Assert.Throws<InvalidDataException>(() => ContractValidation.Validate(w)); }
    [Fact] public void ImmediateHoldDuringCrossingCannotInvalidateSeparation() { var s = New(count: 12); Issue(s, Order() with { A = new(-45000, -55000), B = new(65000, -55000) }); s.AdvanceTo(8); Issue(s, Order("request:stop", RegionalAction.Hold)); s.AdvanceTo(80); ContractValidation.Validate(s.DiagnosticSnapshot()); Assert.All(s.DiagnosticSnapshot().Region!.Units.Where(u => u.Commander == ContractFixture.Officer), u => Assert.Empty(u.Route)); }

    [Fact] public void GlobalRequestIdsCannotBeReusedAfterEnteringRoadMode() { var s = New(); var r = Order(action: RegionalAction.Hold); Issue(s, r); Assert.Equal(ResultCode.Accepted, s.SetRegionalActive(false, s.Revision).Code); var road = TravelWorld.Move(s.DiagnosticSnapshot(), r.Id.Value, "fork"); Assert.Equal(ResultCode.IdPayloadConflict, s.Submit(road, s.Revision).Code); }
    [Fact] public void MalformedAndOverflowCoordinatesDoNotMutateTheWorld() { var s = New(); var before = ContractJson.Write(s.DiagnosticSnapshot()); Assert.Equal(ResultCode.NotAvailable, s.IssueRegional(Order() with { A = null! }, s.Revision).Code); Assert.Equal(ResultCode.NotAvailable, s.IssueRegional(Order() with { A = new(long.MaxValue, long.MinValue) }, s.Revision).Code); Assert.Equal(before, ContractJson.Write(s.DiagnosticSnapshot())); }
    [Fact] public void FutureRecognitionCannotBeSmuggledIntoSave() { var s = New(); Issue(s, Order()); var w = s.DiagnosticSnapshot(); w.Region = w.Region! with { Commands = w.Region.Commands.Select(c => c with { RecognizedAt = 1000 }).ToArray() }; Assert.Throws<InvalidDataException>(() => ContractValidation.Validate(w)); }
[Fact] public void RoadInspectionAtAnchorSurvivesLaterFieldMovement(){var s=New();var edge=BranchRoutes.GraphEdges(s.DiagnosticSnapshot()).First(e=>e.From=="castle"||e.To=="castle");Assert.Equal(ResultCode.Accepted,s.InspectRoad(ContractFixture.Officer,edge.Id,s.Revision).Code);Issue(s,Order());s.AdvanceTo(40);ContractValidation.Validate(s.DiagnosticSnapshot());}
[Fact] public void RadiusAlsoClearsTheDiagonalCornerOfACliff(){Assert.False(RegionalGround.Walkable(new(39500,39500)));Assert.True(RegionalGround.Walkable(new(39000,39000)));}
}
